VALUES (7131, 'tt0338526', NULL, 'Van Helsing', 'Van Helsing', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/gsFun8nATm52aGHeT8ueAel98nE.jpg', 'https://image.tmdb.org/t/p/original/d72ROyJqXQtw2OupW0l15eicRAF.jpg', 'Famed monster slayer Gabriel Van Helsing is dispatched to Transylvania to assist the last of the Valerious bloodline in defeating Count Dracula. Anna Valerious reveals that Dracula has formed an unholy alliance with Dr. Frankenstein''s monster and is hell-bent on exacting a centuries-old curse on her family.', NULL, NULL, 16.076, 6.431, 0, 7.59322535211267535e+01, '2026-07-15 12:01:52', '2026-10-31 23:47:58')
