VALUES (10212, 'tt0129332', NULL, 'Ravenous', 'Ravenous', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/5f7pY4Uzyt4ZNWhHyd1dJhIF4Gc.jpg', 'https://image.tmdb.org/t/p/original/mBw7GMmRycQHFXRUjn70KrzCJCq.jpg', 'After arriving at his new, remote Army outpost, Capt. John Boyd and his regiment aid a wounded frontiersman who recounts a horrifying tale of a wagon train murdered by its supposed guide – a vicious U.S. Army colonel gone rogue. Fearing the worst, the regiment heads out into the wilderness to verify the gruesome claims.', NULL, NULL, 3.7032, 6.8, 0, 30.7088, '2026-07-15 12:01:52', '2026-10-31 23:47:58')
