VALUES (50456, 'tt0993842', NULL, 'Hanna', 'Hanna', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/6QDeHwBXDHbCbuzStgUpuUAqnap.jpg', 'https://image.tmdb.org/t/p/original/qq39KWLKBBJmOtj54grO58XyoXG.jpg', 'Raised by her father, an ex-CIA agent, in the wilds of Finland, Hanna''s upbringing has been geared to making her the perfect assassin. Sent into the world by her father on a mission, Hanna journeys across Europe, eluding agents dispatched after her by a ruthless intelligence operative. As she nears her ultimate target, Hanna faces startling revelations about her existence.', NULL, NULL, 5.9407, 6.584, 0, 15.994, '2026-07-15 12:01:52', '2026-10-31 23:47:58')
