VALUES (40074, 'tt0075666', NULL, 'Alucarda', 'Alucarda, la hija de las tinieblas', 'movie', 1977, 'https://image.tmdb.org/t/p/w500/auZZ7zqm7qbLWBTmq4S2fO6L64m.jpg', 'https://image.tmdb.org/t/p/original/qP48rdzoPRPipo5vvsRfWWuTtjt.jpg', 'After the death of her parents, young Justine is sent to live in a convent, where she meets and falls in love with the mysterious and macabre Alucarda. However, Alucarda has friends in low places... very low places. And a blood pact has just granted them entry to the church.', NULL, NULL, 2.8595, 6.488, 0, 1.81461538461538474e+01, '2026-07-15 12:01:52', '2026-10-31 23:47:58')
