VALUES (1587, 'tt0108550', NULL, 'What''s Eating Gilbert Grape', 'What''s Eating Gilbert Grape', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/8FxWgsfDNosewo7H65oE4QkOb7g.jpg', 'https://image.tmdb.org/t/p/original/m05zMH2I7aEOP4zc0JYOdqR4JUD.jpg', 'Gilbert Grape is a small-town young man with a lot of responsibility. Chief among his concerns are his mother, who is so overweight that she can''t leave the house, and his mentally impaired younger brother, Arnie, who has a knack for finding trouble. Settled into a job at a grocery store and an ongoing affair with local woman Betty Carver, Gilbert finally has his life shaken up by the free-spirited Becky.', NULL, NULL, 8.0702, 7.654, 0, 4.76481395348837182e+01, '2026-07-15 12:01:52', '2026-10-31 23:47:58')
