VALUES (634, 'tt0243155', NULL, 'Bridget Jones''s Diary', 'Bridget Jones''s Diary', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/olMTi7uCaec9Yr3Ar07D2SIja1G.jpg', 'https://image.tmdb.org/t/p/original/9rSpxsMhG1FnFtUDdvSAXdtLtb3.jpg', 'Bridget Jones is an average woman struggling against expectations. As a New Year''s resolution, Bridget decides to take control of her life, starting by keeping a diary in which she will always tell the complete truth. Her charming boss takes an interest in her, and she cannot stop running into a rather disagreeable acquaintance whom Bridget cannot help finding quietly attractive.', NULL, NULL, 9.6996, 6.736, 0, 11.875, '2026-07-15 12:01:52', '2026-10-31 23:47:58')
