VALUES (40008, 'tt2243973', NULL, 'Hannibal', 'Hannibal', 'tv', 2013, 'https://image.tmdb.org/t/p/w500/pbV2eLnKSIm1epSZt473UYfqaeZ.jpg', 'https://image.tmdb.org/t/p/original/vlG182ZY2WMzD5bjFZNnhyvv5V4.jpg', 'Both a gift and a curse, Graham has the extraordinary ability to think like his prey—he sees what they see, feels what they feel. But while Graham is pursuing an especially troubling, cannibalistic murderer, Special Agent Jack Crawford teams him with a highly respected psychiatrist – a man with a taste for the criminal minded – Dr. Hannibal Lecter.', NULL, NULL, 43.0296, 8.265, 0, 24.729, '2026-07-15 12:01:52', '2026-10-31 23:47:58')
