VALUES (27040, 'tt0036154', NULL, 'Meshes of the Afternoon', 'Meshes of the Afternoon', 'movie', 1943, 'https://image.tmdb.org/t/p/w500/yHjEjRU81RcxKFNU5hhiPYMzlsu.jpg', 'https://image.tmdb.org/t/p/original/otRHDr3aMJboh9N4AMbuKKnlHYL.jpg', 'A woman returning home falls asleep and has vivid dreams that may or may not be happening in reality. Through repetitive images and complete mismatching of the objective view of time and space, her dark inner desires play out on-screen.', NULL, NULL, 2.4221, 7.569, 0, 1.29633333333333329e+01, '2026-07-15 12:01:52', '2026-10-31 23:47:58')
