VALUES (807, 'tt0114369', NULL, 'Se7en', 'Se7en', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/191nKfP0ehp3uIvWqgPbFmI4lv9.jpg', 'https://image.tmdb.org/t/p/original/i5H7zusQGsysGQ8i6P361Vnr0n2.jpg', 'Two homicide detectives are on a desperate hunt for a serial killer whose crimes are based on the "seven deadly sins" in this dark and haunting film that takes viewers from the tortured remains of one victim to the next. The seasoned Det. Somerset researches each sin in an effort to get inside the killer''s mind, while his novice partner, Mills, scoffs at his efforts to unravel the case.', NULL, NULL, 42.05, 8.383, 0, 7.51602777777777788e+01, '2026-07-15 12:01:52', '2026-10-31 23:47:58')
