VALUES (6282, 'tt0200550', NULL, 'Coyote Ugly', 'Coyote Ugly', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/xYM0laKrEqjiRSQNvqRrXPXN3iL.jpg', 'https://image.tmdb.org/t/p/original/f2MzXz3vjuNtSPn17ugFa6oTUmc.jpg', 'Graced with a velvet voice, 21-year-old Violet Sanford heads to New York to pursue her dream of becoming a songwriter only to find her aspirations sidelined by the accolades and notoriety she receives at her "day" job as a barmaid at Coyote Ugly. The "Coyotes" as they are affectionately called tantalize customers and the media alike with their outrageous antics, making Coyote Ugly the watering hole for guys on the prowl.', NULL, NULL, 9.7966, 6.257, 0, 2.02786666666666661e+01, '2026-07-15 12:01:52', '2026-10-31 23:47:58')
