VALUES (10956, 'tt0245686', NULL, 'Joe Dirt', 'Joe Dirt', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/yykDEtHk6DMtZK8EaxW88YyQ054.jpg', 'https://image.tmdb.org/t/p/original/1g04YnMJQvWFRKOXJlUeZe1rOxF.jpg', 'Joe Dirt is a janitor with a mullet hairdo, acid-washed jeans and a dream to find the parents that he lost at the Grand Canyon when he was a belligerent, trailer park-raised eight-year-old. Now, blasting Van Halen in his jacked-up economy car, the irrepressibly optimistic Joe hits the road alone in search of his folks.', NULL, NULL, 4.2987, 5.648, 0, 2.7734782608695653e+01, '2026-07-15 12:01:52', '2026-10-31 23:47:58')
