VALUES (1213, 'tt0134119', NULL, 'The Talented Mr. Ripley', 'The Talented Mr. Ripley', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/6ojHgqtIR41O2qLKa7LFUVj0cZa.jpg', 'https://image.tmdb.org/t/p/original/51UDa3IuGyiKGe2MgMcLGvJE2Fm.jpg', 'Tom Ripley is a calculating young man who believes it''s better to be a fake somebody than a real nobody. Opportunity knocks in the form of a wealthy U.S. shipbuilder who hires Tom to travel to Italy to bring back his playboy son, Dickie. Ripley worms his way into the idyllic lives of Dickie and his girlfriend, plunging into a daring scheme of duplicity, lies and murder.', NULL, NULL, 10.8651, 7.202, 0, 8.02027631578947364e+01, '2026-07-15 12:01:52', '2026-10-31 23:47:58')
