VALUES (4538, 'tt0838221', NULL, 'The Darjeeling Limited', 'The Darjeeling Limited', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/oSW5OVXTulaIXcoNwJAp5YEKpbP.jpg', 'https://image.tmdb.org/t/p/original/hKJ513GbmTSmTXJU1uCXclh5Wkh.jpg', 'Three American brothers who have not spoken to each other in a year set off on a train voyage across India with a plan to find themselves and bond with each other -- to become brothers again like they used to be. Their "spiritual quest", however, veers rapidly off-course (due to events involving over-the-counter pain killers, Indian cough syrup, and pepper spray).', NULL, NULL, 5.1592, 7.141, 0, 2.80909090909090934e+01, '2026-07-15 12:01:52', '2026-10-31 23:47:58')
