VALUES (1427, 'tt0396171', NULL, 'Perfume: The Story of a Murderer', 'Perfume: The Story of a Murderer', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/2wrFrUej8ri5EpjgIkjKTAnr686.jpg', 'https://image.tmdb.org/t/p/original/kgHYRHQ5BZM1mxsy1MSZepNjMiR.jpg', 'Jean-Baptiste Grenouille, born in the stench of 18th century Paris, develops a superior olfactory sense, which he uses to create the world''s finest perfumes. However, his work takes a dark turn as he tries to preserve scents in the search for the ultimate perfume.', NULL, NULL, 11.7331, 7.379, 0, 29.8852, '2026-07-15 12:01:52', '2026-10-31 23:47:58')
