VALUES (2907, 'tt0101272', NULL, 'The Addams Family', 'The Addams Family', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/qFf8anju5f2epI0my8RdwwIXFIP.jpg', 'https://image.tmdb.org/t/p/original/7OxGhxUYAdtuike29VMzEFxJx7y.jpg', 'When a man claiming to be long-lost Uncle Fester reappears after 25 years lost, the family plans a celebration to wake the dead. But the kids barely have time to warm up the electric chair before Morticia begins to suspect Fester is fraud when he can''t recall any of the details of Fester''s life.', NULL, NULL, 17.6149, 7.082, 0, 2.75168181818181842e+01, '2026-07-15 12:01:52', '2026-10-31 23:47:58')
