VALUES (504, 'tt0340855', NULL, 'Monster', 'Monster', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/sWPKG1GX0woLNBuvDZkwZC8Q3Ub.jpg', 'https://image.tmdb.org/t/p/original/nUJk4UjWS9YvBJUepCWziQ1QYSf.jpg', 'In 1989, prostitute Aileen Wuornos befriends and enters a relationship with a young woman named Selby. Determined to straighten out her life, Aileen''s limited education lands her back on the corner. She''s raped by a trick, who she kills. A string of murder and robbery follows that ultimately leads Aileen to becoming America''s first female serial killer.', NULL, NULL, 8.3418, 7.202, 0, 2.42144444444444459e+01, '2026-07-15 12:01:52', '2026-10-31 23:47:58')
