VALUES (68726, 'tt1663662', NULL, 'Pacific Rim', 'Pacific Rim', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/mmznhaQDwlHWpUwKuNxtQiubbmM.jpg', 'https://image.tmdb.org/t/p/original/9X7Im1YuBhyHYVD8r7CAONPJR5k.jpg', 'Using massive piloted robots to combat the alien threat, Earth''s survivors take the fight to the invading alien force lurking in the depths of the Pacific Ocean. Nearly defenseless in the face of the relentless enemy, the forces of mankind have no choice but to turn to two unlikely heroes who now stand as Earth''s final hope against the mounting apocalypse.', NULL, NULL, 16.1085, 6.951, 0, 2.6637391304347826e+01, '2026-07-20 01:02:04', '2026-10-31 23:47:58')
