VALUES (18183, 'tt0103994', NULL, 'Like Water for Chocolate', 'Como agua para chocolate', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/itwUdMqLmPfhtGJ44hiDxkqZhiq.jpg', 'https://image.tmdb.org/t/p/original/fi7gBF2nfIGWF9MuOhuEr6rkgBQ.jpg', 'Tita is passionately in love with Pedro, but her controlling mother forbids her from marrying him. When Pedro marries her sister, Tita throws herself into her cooking and discovers she can transfer her emotions through the food she prepares, infecting all who eat it with her intense heartbreak.', NULL, NULL, 2.5682, 7.282, 0, 4.34866666666666645e+01, '2026-07-20 01:02:04', '2026-10-31 23:47:58')
