VALUES (23488, 'tt1235124', NULL, 'Dorian Gray', 'Dorian Gray', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/uRKt8nYdy7EO4uqeKVVpZRmqrxF.jpg', 'https://image.tmdb.org/t/p/original/ij9ai1FDd2ErfRJ8PJrAWakzVEo.jpg', 'Seduced into the decadent world of Lord Henry Wotton, handsome young aristocrat Dorian Gray becomes obsessed with maintaining his youthful appearance, and commissions a special portrait that will weather the winds of time while he remains forever young. When Gray''s obsession spirals out of control, his desperate attempts to safeguard his secret turn his once-privileged life into a living hell.', NULL, NULL, 4.5256, 6.0, 0, 6.255, '2026-07-20 04:02:06', '2026-10-31 23:47:58')
