VALUES (978, 'tt0120102', NULL, 'Seven Years in Tibet', 'Seven Years in Tibet', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/qm87HHUew8ICtUCM4asO3gFYvby.jpg', 'https://image.tmdb.org/t/p/original/athnSvS41TEHOSK2Ax0LAM0ulDp.jpg', 'Austrian mountaineer Heinrich Harrer journeys to the Himalayas without his family to head an expedition in 1939. But when World War II breaks out, the arrogant Harrer falls into Allied forces'' hands as a prisoner of war. He escapes with a fellow detainee and makes his way to Lhasa, Tibet, where he meets the 14-year-old Dalai Lama, whose friendship ultimately transforms his outlook on life.', NULL, NULL, 8.4915, 7.169, 0, 16.6675, '2026-07-21 03:32:24', '2026-10-31 23:47:58')
