VALUES (4481, 'tt0091480', NULL, 'Manon of the Spring', 'Manon des sources', 'movie', 1986, 'https://image.tmdb.org/t/p/w500/1qpu6Zc1PSDL3UbDNIZJ6YuhJDW.jpg', 'https://image.tmdb.org/t/p/original/3ejcvnHxMFfCbnFi736cXi1ChH1.jpg', 'In this, the sequel to Jean de Florette, Manon has grown into a beautiful young shepherdess living in the idyllic Provencal countryside. She plots vengeance on the men who greedily conspired to acquire her father''s land years earlier.', NULL, NULL, 3.0976, 7.574, 0, 10.29, '2026-07-21 03:32:24', '2026-10-31 23:47:58')
