VALUES (47640, 'tt2654620', NULL, 'The Strain', 'The Strain', 'tv', 2014, 'https://image.tmdb.org/t/p/w500/2BWErT9QcADpf2G4BZ769eSnFTP.jpg', 'https://image.tmdb.org/t/p/original/4YnAZ1KO9goeS4c06VO7HXiO3oO.jpg', 'A high concept thriller that tells the story of Dr. Ephraim Goodweather, the head of the Center for Disease Control Canary Team in New York City. He and his team are called upon to investigate a mysterious viral outbreak with hallmarks of an ancient and evil strain of vampirism. As the strain spreads, Eph, his team, and an assembly of everyday New Yorkers, wage war for the fate of humanity itself.', NULL, NULL, 33.537, 7.466, 0, 1.12928571428571427e+01, '2026-07-21 03:32:24', '2026-10-31 23:47:58')
