VALUES (25095, 'tt0104181', NULL, 'Wuthering Heights', 'Wuthering Heights', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/lV8zMPqaK8Qg39zKLzfvnYkiBiC.jpg', 'https://image.tmdb.org/t/p/original/60OypzgF62FE8PWxXi5zSI1bLyS.jpg', 'Young orphan Heathcliff is adopted by the wealthy Earnshaw family and moves into their estate, Wuthering Heights. Soon, the new resident falls for his compassionate foster sister, Cathy. The two share a remarkable bond that seems unbreakable until Cathy, feeling the pressure of social convention, suppresses her feelings and marries Edgar Linton, a man of means who befits her stature. Heathcliff vows to win her back.', NULL, NULL, 4.7104, 6.657, 0, 9.10333333333333349e+00, '2026-07-29 20:51:09', '2026-10-31 23:47:58')
