VALUES (1197137, 'tt29644189', NULL, 'Black Phone 2', 'Black Phone 2', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/vBOpqxW0SDhACwEO2LZT29DuNG2.jpg', 'https://image.tmdb.org/t/p/original/6zKjoOOb3OZnZuiHtQZn4Kd69Gq.jpg', 'Four years after defeating The Grabber, Finney Blake is struggling with life after captivity. When his younger sister Gwen begins receiving calls in her dreams from the Black Phone and seeing disturbing visions of three boys being stalked at a winter camp, the siblings become determined to solve the mystery and confront a killer who has grown more powerful in death and more significant to them than either could imagine.', NULL, NULL, 14.0195, 6.619, 0, 10.5175, '2026-07-29 20:51:09', '2026-10-31 23:47:58')
