VALUES (175, 'tt0095250', NULL, 'The Big Blue', 'Le Grand Bleu', 'movie', 1988, 'https://image.tmdb.org/t/p/w500/3t5t7yaFiTJQlqxiTkXJMFZdkh3.jpg', 'https://image.tmdb.org/t/p/original/1J28PJOkusMN5Ab9Q3oF310e11k.jpg', 'Childhood friends Jacques and Enzo share a passion for the danger of free diving. Jacques, following in the footsteps of his father, who died at sea when Jacques was a boy, harbors a remarkable ability to adjust his heart rate and breathing patterns in the water, with his vital signs more closely resembling those of dolphins than men.', NULL, NULL, 6.0559, 7.441, 0, 12.325, '2026-07-29 20:51:09', '2026-10-31 23:47:58')
