VALUES (21575, 'tt1235166', NULL, 'A Prophet', 'Un prophète', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/x9Jb8kewBHPzjTtgCQvoQoDsy4d.jpg', 'https://image.tmdb.org/t/p/original/jEJDjDBT6KCoS4WOBq68vZMbFk2.jpg', 'Sentenced to six years in prison, Malik El Djebena is alone in the world and can neither read nor write. On his arrival at the prison, he seems younger and more brittle than the others detained there. At once he falls under the sway of a group of Corsicans who enforce their rule in the prison. As the ''missions'' go by, he toughens himself and wins the confidence of the Corsican group.', NULL, NULL, 4.344, 7.551, 0, 6.60999999999999943e+00, '2026-07-30 18:28:39', '2026-10-31 23:47:58')
