VALUES (8293, 'tt0104454', NULL, 'Howards End', 'Howards End', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/1009nhfj28VhhQnVadtjkOacduX.jpg', 'https://image.tmdb.org/t/p/original/novvibtQv0B4psRxuqvd8g2qS5M.jpg', 'A saga of class relations and changing times in an Edwardian England on the brink of modernity, the film centers on liberal Margaret Schlegel, who, along with her sister Helen, becomes involved with two couples: wealthy, conservative industrialist Henry Wilcox and his wife Ruth, and the downwardly mobile working-class Leonard Bast and his mistress Jackie.', NULL, NULL, 3.9277, 7.0, 0, 11.894, '2026-07-31 03:33:23', '2026-10-31 23:47:58')
