VALUES (926, 'tt0177789', NULL, 'Galaxy Quest', 'Galaxy Quest', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/fZXSwgZknp81vmciTb86rw0MejV.jpg', 'https://image.tmdb.org/t/p/original/yzQ0mkz1OUJKtUK1NWp53jiGcaJ.jpg', 'For four years, the courageous crew of the NSEA Protector —  Commander Peter Quincy Taggart, Lieutenant Tawny Madison, and Doctor Lazarus — set off on a thrilling and often dangerous mission in space... until their series was cancelled! Now, twenty years later, aliens under attack have mistaken the Galaxy Quest television transmissions for "historical documents" and beam up the crew of has-been actors to save the universe. With no script, no director, and no clue, the actors must turn in the performances of their lives.', NULL, NULL, 8.733, 7.09, 0, 13.82, '2026-08-05 03:13:48', '2026-10-31 23:47:58')
