VALUES (29095, 'tt0096426', NULL, 'Waxwork', 'Waxwork', 'movie', 1988, 'https://image.tmdb.org/t/p/w500/48RXt1Zu8iNL0mgCojydmqBsjsC.jpg', 'https://image.tmdb.org/t/p/original/x0sEJCg6UsLoGs8r9b4l8rp1oxe.jpg', 'Wealthy slacker Mark, his new girlfriend Sarah, and their friends, are invited to a special showing at a mysterious wax museum which displays eighteen of the most evil men of all time. After his ex-girlfriend and another friend disappear, Mark becomes suspicious…', NULL, NULL, 3.4478, 6.2, 0, 11.02, '2026-10-17 04:47:13', '2026-10-31 23:47:58')
