VALUES (598896, 'tt10265034', NULL, 'Land', 'Land', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/6pYhDPzYPGKvDYpxdf0IUE3RDAS.jpg', 'https://image.tmdb.org/t/p/original/2ZzmfwgvVh2KLH4A8HMzX5TytAc.jpg', 'Edee, in the aftermath of an unfathomable event, finds herself unable to stay connected to the world she once knew and in the face of that uncertainty, retreats to the magnificent, but unforgiving, wilds of the Rockies. After a local hunter brings her back from the brink of death, she must find a way to live again.', NULL, NULL, 3.8259, 6.683, 0, 10.525, '2026-10-17 15:53:06', '2026-10-31 23:47:58')
